// Filter and clean job data
const jobs = [];
const items = $input.all();

for (const item of items) {
  if (item.json.results) {
    // Indeed jobs
    for (const job of item.json.results) {
      if (job.snippet && job.jobtitle) {
        jobs.push({
          source: 'indeed',
          title: job.jobtitle,
          company: job.company,
          location: job.formattedLocation,
          description: job.snippet,
          url: job.url,
          posted_date: job.date,
          experience_level: 'entry',
          skills_required: extractSkills(job.snippet + ' ' + job.jobtitle)
        });
      }
    }
  }

  if (item.json.jobs) {
    // Naukri jobs
    for (const job of item.json.jobs) {
      jobs.push({
        source: 'naukri',
        title: job.title,
        company: job.company,
        location: job.location,
        description: job.description,
        url: job.url,
        posted_date: job.postedDate,
        experience_level: 'entry',
        skills_required: extractSkills(job.description + ' ' + job.title)
      });
    }
  }
}

function extractSkills(text) {
  const skillKeywords = [
    'excel', 'data entry', 'microsoft office', 'communication',
    'customer service', 'sales', 'marketing', 'programming',
    'python', 'javascript', 'html', 'css', 'sql', 'accounting',
    'bookkeeping', 'typing', 'computer', 'internet'
  ];

  const foundSkills = [];
  const lowerText = text.toLowerCase();

  for (const skill of skillKeywords) {
    if (lowerText.includes(skill)) {
      foundSkills.push(skill);
    }
  }

  return foundSkills;
}

return jobs.map(job => ({ json: job }));

// Filter and clean course data
const courses = [];
const items = $input.all();

for (const item of items) {
  if (item.json.elements) {
    // Coursera courses
    for (const course of item.json.elements) {
      if (course.name) {
        courses.push({
          source: 'coursera',
          title: course.name,
          description: course.description || '',
          url: `https://coursera.org/learn/${course.slug}`,
          price: course.price || 'free',
          duration: course.workload || 'self-paced',
          skills_taught: extractSkills(course.name + ' ' + (course.description || '')),
          difficulty: 'beginner'
        });
      }
    }
  }

  if (item.json.results) {
    // edX courses
    for (const course of item.json.results) {
      courses.push({
        source: 'edx',
        title: course.name,
        description: course.short_description || '',
        url: `https://edx.org${course.course_runs[0]?.marketing_url || ''}`,
        price: course.course_runs[0]?.seats?.find(s => s.type === 'audit')?.price || 'free',
        duration: course.course_runs[0]?.weeks_to_complete || 'self-paced',
        skills_taught: extractSkills(course.name + ' ' + (course.short_description || '')),
        difficulty: 'beginner'
      });
    }
  }
}

function extractSkills(text) {
  const skillKeywords = [
    'excel', 'data analysis', 'microsoft office', 'communication',
    'customer service', 'sales', 'marketing', 'programming',
    'python', 'javascript', 'html', 'css', 'sql', 'accounting',
    'bookkeeping', 'typing', 'computer skills', 'digital literacy'
  ];

  const foundSkills = [];
  const lowerText = text.toLowerCase();

  for (const skill of skillKeywords) {
    if (lowerText.includes(skill)) {
      foundSkills.push(skill);
    }
  }

  return foundSkills;
}

// Filter courses under ₹500 or free
const affordableCourses = courses.filter(course => {
  const price = course.price;
  if (price === 'free' || price === 0) return true;
  if (typeof price === 'string' && price.includes('₹')) {
    const amount = parseInt(price.replace(/[^0-9]/g, ''));
    return amount <= 500;
  }
  return false;
});

return affordableCourses.map(course => ({ json: course }));

// AI-powered job and course matching
const users = $input.all();
const matches = [];

for (const userItem of users) {
  const user = userItem.json;

  // Create user profile for AI analysis
  const userProfile = {
    interests: user.job_interests?.split(',') || [],
    skills: user.current_skills?.split(',') || [],
    education: user.education_level || 'basic',
    location: user.location || 'India'
  };

  // This would typically call an AI service like OpenAI GPT
  // For now, we'll use rule-based matching
  const jobMatches = findMatchingJobs(userProfile);
  const courseMatches = findMatchingCourses(userProfile, jobMatches);

  matches.push({
    user_id: user.user_id,
    name: user.name,
    email: user.email,
    phone: user.phone,
    preferred_channel: user.preferred_channel,
    matched_jobs: jobMatches.slice(0, 5), // Top 5 jobs
    recommended_courses: courseMatches.slice(0, 3), // Top 3 courses
    learning_plan: generateLearningPlan(courseMatches[0], jobMatches[0])
  });
}

function findMatchingJobs(userProfile) {
  // This would query the jobs table and use AI to match
  // Returning mock data for demonstration
  return [
    {
      title: 'Data Entry Clerk',
      company: 'TechCorp',
