parameters.functionCode:
// Generate personalized reminders and check progress
const learners = $input.all();
const reminders = [];

for (const learnerItem of learners) {
  const learner = learnerItem.json;

  // Calculate days since last activity
  const lastActivity = new Date(learner.last_activity || learner.started_at);
  const daysSinceActivity = Math.floor((Date.now() - lastActivity.getTime()) / (1000 * 60 * 60 * 24));

  let reminderType = 'progress';
  let message = '';

  if (daysSinceActivity >= 3) {
    reminderType = 'comeback';
    message = `Hi! We miss you in your ${learner.course_title} course. You're ${learner.progress}% complete - let's keep the momentum going! 💪`;
  } else if (learner.progress >= 75) {
    reminderType = 'completion';
    message = `Amazing progress! You're ${learner.progress}% through ${learner.course_title}. Just a little more to go! 🎉`;
  } else {
    message = `Daily reminder: Spend 30 minutes on ${learner.course_title} today. You're doing great at ${learner.progress}%! 📚`;
  }

  reminders.push({
    user_id: learner.user_id,
    course_id: learner.course_id,
    course_title: learner.course_title,
    progress: learner.progress,
    reminder_type: reminderType,
    message: message,
    days_since_activity: daysSinceActivity
  });
}

return reminders.map(reminder => ({ json: reminder }));

// Generate weekly digest with achievements, new opportunities, and progress
