    },
    next_week_goals: [
      'Complete Excel certification',
      'Apply to 5 more jobs',
      'Start Communication Skills course'
    ]
  };

  digests.push(weeklyData);
}

return digests.map(digest => ({ json: digest }));

// Process quiz results and update learning progress
const response = $input.first().json;
const aiEvaluation = response.choices[0].message.content;

// Parse AI response to extract structured data
const isCorrect = $json.user_answer.toLowerCase() === $json.correct_answer.toLowerCase();
const scoreDelta = isCorrect ? 5 : -2;

// Update progress based on performance
let progressUpdate = 0;
if (isCorrect) {
  progressUpdate = 2; // 2% progress for correct answer
} else {
  progressUpdate = 0.5; // Still give some progress for attempt
}

const result = {
  user_id: $json.user_id,
  course_id: $json.course_id,
  question_id: $json.question_id,
  is_correct: isCorrect,
  score_delta: scoreDelta,
  progress_delta: progressUpdate,
  ai_feedback: aiEvaluation,
  needs_review: !isCorrect,
  timestamp: new Date().toISOString()
};

return { json: result };

