// Check for achievements and badges
const users = $input.all();
const achievements = [];

for (const userItem of users) {
  const user = userItem.json;

  // Check various achievement criteria
  const userAchievements = [];

  // Learning streak achievements
  if (user.learning_streak >= 7) {
    userAchievements.push({
      type: 'streak',
      title: 'Week Warrior',
      description: '7 days learning streak!',
      icon: '🔥',
      points: 50
    });
  }

  if (user.learning_streak >= 30) {
    userAchievements.push({
      type: 'streak',
      title: 'Learning Legend',
      description: '30 days learning streak!',
      icon: '🏆',
      points: 200
    });
  }

  // Course completion achievements
  if (user.courses_completed >= 1) {
    userAchievements.push({
      type: 'completion',
      title: 'First Graduate',
      description: 'Completed your first course!',
      icon: '🎓',
      points: 100
    });
  }

  // Job application achievements
  if (user.job_applications >= 5) {
    userAchievements.push({
      type: 'application',
      title: 'Job Hunter',
      description: 'Applied to 5 jobs!',
      icon: '🎯',
      points: 75
    });
  }

  // Quiz performance achievements
  if (user.quiz_score >= 80) {
    userAchievements.push({
      type: 'performance',
      title: 'Quiz Master',
      description: 'Scored 80%+ on quizzes!',
      icon: '🧠',
      points: 60
    });
  }

  if (userAchievements.length > 0) {
    achievements.push({
      user_id: user.user_id,
      name: user.name,
      phone: user.phone,
      email: user.email,
      new_achievements: userAchievements,
      total_points: userAchievements.reduce((sum, ach) => sum + ach.points, 0)
    });
  }
}

return achievements.map(achievement => ({ json: achievement }));

